pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 amount, bytes calldata data) public {
        // 1. ensure nonOwner is not the original owner (sender in setUp is this test contract)
        vm.assume(nonOwner != address(this));
        // bound amount to something reasonable, but allow zero; keep domain wide.
        uint256 balBefore = address(c).balance;
        // 2. give nonOwner some ether to potentially send and call as non-owner
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        // use try/catch because a non-owner call to sendMoney should revert on the reference contract;
        // we don't care if it reverts or not, we just observe balance change.
        try c.sendMoney(address(0xdead), 0, data) {} catch {}
        // 3. The invariant: if the caller is not the owner, the contract balance must be the same as before.
        // The reference C enforces onlyOwner, so non-owner call always reverts -> balance unchanged.
        // The mutant allows the call, so balance can decrease when amount > 0.
        assertTrue(address(c).balance == balBefore);
    }
}

