pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict depositAmount to non-zero and bound it to a reasonable range to avoid overflow in minting
        vm.assume(depositAmount > 0);
        depositAmount = bound(depositAmount, 1, 1000 ether);
        // withdrawAmount must be <= depositAmount to test the correct withdrawal logic
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Fund the contract with a deposit
        vm.deal(address(c), depositAmount);
        // Record the owner's initial balance
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Perform a partial withdrawal to ensure the state is set up
        vm.prank(owner);
        c.withdraw(withdrawAmount);

        // Now the contract should have remaining balance: depositAmount - withdrawAmount
        uint256 remainingBalance = address(c).balance;
        vm.assume(remainingBalance > 0);

        // Record the owner's balance before withdrawAll
        uint256 ownerBalanceBeforeWithdrawAll = owner.balance;
        uint256 contractBalanceBeforeWithdrawAll = address(c).balance;

        // Call withdrawAll as owner
        vm.prank(owner);
        c.withdrawAll();

        // After withdrawAll, the owner's balance must have increased by exactly the contract's balance before the call.
        // The buggy version only transfers 1 wei, so the owner's balance increase will be 1 instead of the full amount.
        assertTrue(owner.balance == ownerBalanceBeforeWithdrawAll + contractBalanceBeforeWithdrawAll);
    }
}

